export function MobileNav() {
  const pathname = usePathname();

  const isActive = (href: string) => {
    if (href === "/vendor") return pathname === "/vendor";
    return pathname.startsWith(href);
  };

  return (
    <nav
      className="lg:hidden fixed bottom-0 left-0 right-0 z-30 border-t border-border bg-card"
      aria-label="Navigation mobile vendeur"
    >
      <ul className="flex items-center justify-around py-1" role="list">
        {MOBILE_NAV_ITEMS.map((item) => {
          const active = isActive(item.href);
          return (
            <li key={item.label}>
              <Link
                href={item.href}
                className={[
                  "flex flex-col items-center gap-0.5 rounded-lg px-2 py-1.5 text-xs transition-colors",
                  active
                    ? "text-primary"
                    : "text-muted-foreground",
                ].filter(Boolean).join(" ")}
                aria-current={active ? "page" : undefined}
              >
                <span className="h-5 w-5">{item.icon}</span>
                <span>{item.label}</span>
              </Link>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}